CREATE TABLE IF NOT EXISTS {target_table} (
    calculated_at TIMESTAMP COMMENT 'Момент Gold snapshot: 00:00 или 12:00 Asia/Tashkent; часть уникального ключа',
    account_id INT COMMENT 'Положительный идентификатор пользователя; часть уникального ключа',
    l5_category_id INT COMMENT 'Положительный идентификатор категории L5; часть уникального ключа',
    ACCOUNT_L5__n_clicks_3d INT COMMENT 'Число PRODUCT_VIEW-сессий товаров категории L5 для пользователя за 3 дней',
